INSERT INTO CoffeeOrdersDb.CoffeeOrders.Coffees (Id, Name, Description, SkuCode, Photo, CreatedBy, CreatedDate, UpdatedBy, UpdatedDate, IsActive) VALUES (N'5DEB9271-E8FB-4E00-BBAD-2587EAAADB34', N'Caffe Latte', N'Smooth and comforting, this classic beverage combines a single shot of espresso with a generous amount of steamed milk, topped with a light layer of velvety microfoam. Perfect for those who prefer a milder, creamier coffee experience.', N'COFLAT0002', null, N'System', N'2026-10-15T09:40:21.87', N'System', N'2026-10-15T09:40:21.87', 1);
INSERT INTO CoffeeOrdersDb.CoffeeOrders.Coffees (Id, Name, Description, SkuCode, Photo, CreatedBy, CreatedDate, UpdatedBy, UpdatedDate, IsActive) VALUES (N'BECC5F3C-3B10-43EF-B39C-355838BBE0A5', N'Cold Brew', N'Coarsely ground coffee beans steeped in cold filtered water for 12 to 24 hours. This slow-extraction method yields an ultra-smooth, naturally sweet coffee with significantly lower acidity and higher caffeine content, served over ice.', N'COFCBR0005', null, N'System', N'2026-10-15T09:44:33.826', N'System', N'2026-10-15T09:44:33.826', 1);
INSERT INTO CoffeeOrdersDb.CoffeeOrders.Coffees (Id, Name, Description, SkuCode, Photo, CreatedBy, CreatedDate, UpdatedBy, UpdatedDate, IsActive) VALUES (N'C8616DDC-77DC-48BC-908F-A07753DDAD87', N'Cappuccino', N'An Italian favorite featuring equal parts espresso, steamed milk, and rich milk foam. It offers a balanced, robust coffee taste with a deliciously airy texture, often finished with a light dusting of cocoa powder or cinnamon.', N'COFCAP0003', null, N'System', N'2026-10-15T09:41:15.88', N'System', N'2026-10-15T09:41:15.88', 1);
INSERT INTO CoffeeOrdersDb.CoffeeOrders.Coffees (Id, Name, Description, SkuCode, Photo, CreatedBy, CreatedDate, UpdatedBy, UpdatedDate, IsActive) VALUES (N'4C927395-4E72-40FB-953E-C7157AE53AB8', N'Caramel Macchiato', N'A sweet and indulgent treat made by "marking" freshly steamed milk with a shot of vanilla-infused espresso, then finishing it off with a distinctive, crisscrossed drizzle of rich, buttery caramel sauce.', N'COFMAC0004', null, N'System', N'2026-10-15T09:42:42.796', N'System', N'2026-10-15T09:42:42.796', 1);
INSERT INTO CoffeeOrdersDb.CoffeeOrders.Coffees (Id, Name, Description, SkuCode, Photo, CreatedBy, CreatedDate, UpdatedBy, UpdatedDate, IsActive) VALUES (N'884EEA54-752C-46B9-B6D9-DE470AD4A012', N'Classic Espresso', N'A rich, concentrated shot of pure coffee brewed by forcing hot water under high pressure through finely-ground coffee beans. Features a thick, golden crema on top and a bold, intense flavor profile with subtle notes of dark chocolate and caramel.', N'COFESP0001', null, N'System', N'2026-10-15T09:37:56.493', N'System', N'2026-10-15T09:37:56.493', 1);
